import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第80章 回来","description":"","frontmatter":{},"headers":[],"relativePath":"第80章_回来.md","filePath":"第80章_回来.md"}'),_={name:"第80章_回来.md"};function r(u,p,n,s,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第80章-回来" tabindex="-1">第80章 回来 <a class="header-anchor" href="#第80章-回来" aria-label="Permalink to &quot;第80章 回来&quot;">​</a></h1><p>卷四结束在那年六月，她说明年回来。</p><p>那件事的起因很普通。</p><p>她那个展要办第二场，办在我们这边一个城市。</p><p>她的画要被运过来。</p><p>她说，我要跟过去布展，我要待十一天。</p><p>我说，哪个城市。</p><p>她说，澄江隔壁那个。</p><p>我说，那很近。</p><p>她说，对，很近。</p><p>她说，我这次是公费，机票他们出。</p><p>我说，那挺好。</p><p>她说，你看，你今天就讲了一句人话。</p><p>那天晚上我们聊了很多。</p><p>聊的是那十一天要干什么。</p><p>她说，我布展要四天。</p><p>她说，剩下七天我什么事都没有。</p><p>我说，那你来澄江。</p><p>她说，我为什么要来澄江。</p><p>我说，我在这儿。</p><p>她说，我知道你在。</p><p>她说，我来你这儿我要住哪儿。</p><p>我说，我帮你找。</p><p>她说，找一晚上两百。</p><p>我说，我出。</p><p>她说，你出得起吗。</p><p>我说，我出得起这一笔。</p><p>她说，你这一笔出完，你下半年又要吃一个月泡面。</p><p>我说，我不吃泡面，我食堂。</p><p>她说，你食堂一顿十二。</p><p>她说，你算一下我住六天要多少。</p><p>我说，你别算。</p><p>她说，你看，你不让我算。</p><p>她说，你不让我算，就是你知道这个数你不好受。</p><p>那天我们最后没定下来。</p><p>我把那个数算了。</p><p>六天，一晚上两百，一千二。</p><p>一千二是我那一年仓库抽成、发谷子、加上我寒假帮人修了八个电脑剩下的全部。</p><p>我把这个数写在纸上。</p><p>写完我把它折了一下，放进那个备忘录。</p><p>备忘录里已经有三十几条了。</p><p>我存的全是我不能说的那部分。</p><p>郑拓那天晚上从外面回来，看见我还醒着。</p><p>他说，你又不睡。</p><p>我说，我今天有点事。</p><p>他说，你年年有点事。</p><p>他说，你这样迟早把自己弄垮。</p><p>我说，我没事。</p><p>他说，行，你有事你别说。</p><p>他说完躺下去，十分钟后他睡着了。</p><p>他那句话后面半句是对的。</p><p>我这辈子从来没有在她面前说过我有事。</p><p>我只在我自己的备忘录里说。</p><p>我们把这件事放下了。</p><p>放下以后她说了一句。</p><p>她说，反正我要回来。</p><p>她说，等我回来。</p><p>我看到这四个字，先把它们读了第二遍。</p><p>因为这句话有毛病。</p><p>她说的是&quot;等我回来&quot;。</p><p>回来是一个方向，不是一个目的地。</p><p>&quot;我回来找你&quot;，是一个动作有对象。</p><p>&quot;等我回来&quot;，只有她自己往回走。</p><p>谁在原地等，这句话里没写。</p><p>我坐在那儿想这件事想了很久。</p><p>我想我是不是要问。</p><p>我问一句&quot;回哪儿&quot;，我们就这一晚上完了。</p><p>我问一句&quot;回来看谁&quot;，那她就要开始解释。</p><p>她一解释，她就得说清楚她为什么不说&quot;看你&quot;。</p><p>而她说不清楚。</p><p>她不是不喜欢我。</p><p>她是不能把这两个字放在一个她妈会看的号上。</p><p>所以她说的是回来。</p><p>我说，好，我等你。</p><p>她说，你别等我。</p><p>我说，那说什么。</p><p>她说，你说&quot;你回来的时候记得吃饭&quot;。</p><p>我说，那不像话。</p><p>她说，那就说这个。</p><p>她说，你就当这是一句正经的约定。</p><p>她说，正经约定就是不涉及感情的约定。</p><p>她说，涉及感情的约定我签不了。</p><p>那天夜里我在本子上写下这一句。</p><p>我写：她说涉及感情的约定她签不了。</p><p>我写：她说等我回来。</p><p>我写：这两句加起来是：她愿意回来，不愿意回来找我。</p><p>那年夏天我们最后一次长聊，是七月末。</p><p>她说，明年三月展就撤了。</p><p>我说，撤了以后你去哪儿。</p><p>她说，我不知道。</p><p>她说，可能是这边，可能是回国。</p><p>她说，我这两年在攒一样东西。</p><p>我说，攒什么。</p><p>她说，攒一个我可以谁都不用问的选项。</p><p>我说，那需要很多钱。</p><p>她说，需要。</p><p>我说，你有吗。</p><p>她说，我差一点。</p><p>我说，差多少。</p><p>她说，你别问。</p><p>我说，我不问，我算。</p><p>她说，你敢算。</p><p>那晚我们笑了很久。</p><p>我们笑的是同一件事：这一年我们两个谁也不许算，可是我们两个一辈子都在算。</p><p>八月一号，她那边凌晨一点，她说了一句话。</p><p>她说，我要睡了，明年见。</p><p>我说，明年见。</p><p>她说，你把那个箱子放好。</p><p>我说，放好了。</p><p>她说，胶带是不是缠了两道。</p><p>我说，你怎么知道两道。</p><p>她说，你这个人，你干什么东西都是两道。</p><p>她说，你连一封不发的信你都要折两道。</p><p>我说，你今天怎么这么多。</p><p>她说，我要睡了我不讲这些，我明天又不记得我讲过。</p><p>我说，你记得。</p><p>她说，我不知道。</p><p>她说，反正你记得。</p><p>她说，晚安。</p><p>那晚我关了屏幕。</p><p>我这边是凌晨三点四十。</p><p>她那边的凌晨一点，她睡了。</p><p>第二天早上她那边下午五点，我这边夜里十二点，她发了一句。</p><p>她说，我今天要办一件事，我下周可能不太上。</p><p>我说，好。</p><p>她说，你别担心，是好事。</p><p>我说，什么事。</p><p>她说，我把那个专业退了。</p><p>我说，退了你干什么。</p><p>她说，我改去学画画。</p><p>我坐在床上，看着这九个字。</p><p>她说，我妈不知道。</p><p>她说，我下个月告诉她。</p><p>我说，你要我干什么。</p><p>她说，你别干什么。</p><p>她说，我就是先跟你说一声。</p><p>她说，我这个人做决定的时候，我从来没人商量。</p><p>她说，我今天跟你讲，是因为我想让一个人知道。</p><p>她说，一个就够了。</p><p>那年八月，我把那个装本子的箱子从床底下拖出来过一次。</p><p>我看了一眼胶带，没撕。</p><p>我又推回去了。</p><p>我推回去的时候想到她说的那一句。</p><p>她说，等我回来。</p><p>我把这四个字在心里摆了一下。</p><p>摆的位置很清楚：</p><p>她说的是回来。</p><p>不是回来找我。</p><p>这两者的分别，我记了四年。</p><p>而四年以后我才第一次敢承认：</p><p>我当时听见了这个分别。</p><p>我只是没有问。</p><p>因为不问，我可以过完整个夏天。</p><p>问了，我连这个夏天都没有。</p>',154)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
